/**
 * @summary Analyze fleet imbalances and generate rebalancing recommendations
 */
export const analyzeRebalancingResponseRecommendedDroneRegistrationNumberMin = 3;
export const analyzeRebalancingResponseRecommendedDroneRegistrationNumberMax = 50;
export const analyzeRebalancingResponseRecommendedDroneRegistrationNumberRegExp = new RegExp(
    "^[A-Za-z0-9_-]+$"
);

export const analyzeRebalancingResponseItem = zod.object({
    sourceHub: zod
        .object({
            hubId: zod.string().optional(),
            hubName: zod.string().optional(),
            totalDrones: zod.number().optional(),
            availableDrones: zod.number().optional(),
            busyDrones: zod.number().optional(),
            chargingDrones: zod.number().optional(),
            maintenanceDrones: zod.number().optional(),
            droneIds: zod.array(zod.string()).optional(),
            capacityUtilization: zod.number().optional(),
            lastUpdated: zod.iso.datetime({}).optional(),
        })
        .optional(),
    targetHub: zod
        .object({
            hubId: zod.string().optional(),
            hubName: zod.string().optional(),
            totalDrones: zod.number().optional(),
            availableDrones: zod.number().optional(),
            busyDrones: zod.number().optional(),
            chargingDrones: zod.number().optional(),
            maintenanceDrones: zod.number().optional(),
            droneIds: zod.array(zod.string()).optional(),
            capacityUtilization: zod.number().optional(),
            lastUpdated: zod.iso.datetime({}).optional(),
        })
        .optional(),
    recommendedDrone: zod
        .object({
            id: zod.string().optional(),
            registrationNumber: zod
                .string()
                .min(analyzeRebalancingResponseRecommendedDroneRegistrationNumberMin)
                .max(analyzeRebalancingResponseRecommendedDroneRegistrationNumberMax)
                .regex(analyzeRebalancingResponseRecommendedDroneRegistrationNumberRegExp)
                .optional(),
            model: zod.string().optional(),
            manufacturer: zod.string().optional(),
            status: zod.string().optional(),
            homeHubId: zod.string().optional(),
            currentHubId: zod.string().optional(),
            maxPayloadKg: zod.number().optional(),
            maxRangeM: zod.number().optional(),
            batteryHealthPct: zod.number().optional(),
            totalFlightHours: zod.number().optional(),
            capabilities: zod.array(zod.string()).optional(),
            nextMaintenance: zod.iso.datetime({}).optional(),
        })
        .optional(),
    trigger: zod.string().optional(),
    priority: zod.number().optional(),
    reason: zod.string().optional(),
});
export const analyzeRebalancingResponse = zod.array(analyzeRebalancingResponseItem);

